"""Original synthetic teaching fixtures; no real students or scraped answers."""

TOPICS = [
    dict(id='ml', title='Supervised & unsupervised learning', subject='Machine Learning', question='Explain supervised and unsupervised learning. Compare their training data, tasks, and real-world applications.', concepts=['labelled data|labeled data', 'unlabelled data|unlabeled data', 'classification', 'regression', 'clustering', 'prediction|predict'], reference='Supervised learning trains on labelled data, where each input has a known target output. It learns a mapping to make predictions on unseen examples. Classification predicts categories, such as spam or legitimate email. Regression predicts continuous values, such as house prices. Unsupervised learning uses unlabelled data to discover patterns without known targets. Clustering groups similar observations, for example customer segments. The key difference is whether training examples include the desired output. Both methods need representative data and careful evaluation.', partial='Supervised learning uses labelled data to predict outcomes. Classification can identify spam emails. Unsupervised learning discovers patterns in data.', paraphrase='With supervised methods, examples are paired with correct answers so the system can predict a result for a new input. A classifier assigns a category, while regression estimates a number. In contrast, unsupervised methods receive unlabeled data and seek hidden structure. Clustering creates groups of similar customers. Thus the presence of labels determines the learning setup.'),
    dict(id='db', title='Database normalization', subject='Database Systems', question='Explain database normalization through 1NF, 2NF and 3NF, including its benefits and a practical example.', concepts=['redundancy|duplication','atomic','partial dependency|partial dependencies','transitive dependency|transitive dependencies','primary key','foreign key'], reference='Database normalization organizes relational tables to reduce redundancy and prevent update, insertion and deletion anomalies. First normal form requires atomic values and no repeating groups. Second normal form requires 1NF and removes partial dependencies on part of a composite primary key. Third normal form requires 2NF and removes transitive dependencies between non-key attributes. For example, store student and department details in separate tables and connect them with a foreign key. This avoids repeating department information for each student. Normalization improves consistency, although joins can increase query cost.', partial='Normalization reduces redundancy in databases. First normal form requires atomic values. Tables can be split to avoid repeating student information.', paraphrase='To prevent duplication and inconsistent updates, normalization divides a database into related tables. In 1NF each cell holds an atomic value. In 2NF every non-key column depends on the entire primary key, eliminating partial dependencies. In 3NF a non-key column must not depend on another non-key column, eliminating transitive dependencies. A foreign key can link a student table to a department table. This improves consistency but may require additional joins.'),
    dict(id='os', title='Processes, threads & concurrency', subject='Operating Systems', question='Compare a process and a thread. Explain memory isolation, resource sharing, context switching and synchronization.', concepts=['address space|memory space','shared memory|share memory','context switch|context switching','synchronization','race condition|race conditions','mutex|lock'], reference='A process is an executing program with its own address space and operating system resources. A thread is an execution unit inside a process. Threads share memory and resources while maintaining their own stack and registers. Process isolation improves fault containment. A context switch between processes is typically more expensive than between threads in one process. Shared memory enables efficient communication but introduces race conditions. Synchronization using a mutex or lock protects critical sections. For example, worker threads in a server can handle multiple requests but must coordinate updates to shared state.', partial='A process is a program running on a computer. Threads share memory inside the same process. A context switch changes the running task.', paraphrase='Processes execute in separate memory spaces. Several threads can run within one process and share memory, but each has a private stack. Switching execution between these threads usually costs less than a process context switch. Because two threads can modify the same data, race conditions may occur. Synchronization with a mutex or lock restricts access to a critical section. A server uses worker threads to serve concurrent requests.'),
    dict(id='net', title='TCP and UDP transport', subject='Computer Networks', question='Compare TCP and UDP in terms of connection setup, reliability, ordering, overhead and suitable applications.', concepts=['connection','reliable|reliability','ordering|ordered|order','retransmission|retransmissions','overhead','streaming|video|gaming'], reference='TCP is a connection-oriented transport protocol that establishes a connection before data transfer. It provides reliable delivery using acknowledgements and retransmissions. Sequence numbers preserve ordered delivery, and flow and congestion control manage traffic. These mechanisms add overhead and latency. UDP sends independent datagrams without connection setup and does not guarantee delivery or ordering. Its lower overhead suits applications that prefer timely delivery over retransmission, such as live video streaming, voice calls and online gaming. TCP is useful for file transfer and web content where complete reliable delivery matters.', partial='TCP provides reliable data transfer using a connection. UDP is faster in some applications because it has less overhead. Streaming often uses UDP.', paraphrase='A TCP connection maintains state and uses acknowledgements and retransmission to recover lost packets. It delivers data in order with flow control, at the cost of overhead. UDP has no connection handshake and no built-in guarantee that packets arrive or remain ordered. Live video and gaming may prefer this low-latency approach. File downloads favor TCP because completeness matters more than immediate delivery.'),
    dict(id='ds', title='Stacks and queues', subject='Data Structures', question='Compare stacks and queues, describe their operations and time complexity, and give examples of their applications.', concepts=['lifo|last in first out','fifo|first in first out','push','pop','enqueue','dequeue'], reference='A stack follows last in first out (LIFO): the most recently added element is removed first. Push adds an item to the top, and pop removes the top item. A queue follows first in first out (FIFO): the earliest added element is removed first. Enqueue adds to the rear, and dequeue removes from the front. With appropriate array or linked implementations these operations take constant O(1) time. Stacks support function calls, undo and depth-first search. Queues support scheduling, print jobs and breadth-first search. An empty structure must handle removal safely to avoid underflow.', partial='A stack uses LIFO. Push inserts an element and pop removes it. Stacks are useful for undo operations.', paraphrase='Stacks remove the newest item first, which is called LIFO. Their push and pop operations work at the top. Queues remove the oldest item first, called FIFO. Enqueue inserts at the back and dequeue removes at the front. These operations can run in O(1) time with a suitable implementation. Undo history uses a stack while a printer waiting list uses a queue. Removing from an empty collection requires an underflow check.'),
    dict(id='se', title='Testing across the software lifecycle', subject='Software Engineering', question='Explain unit, integration and system testing, and discuss regression testing with practical examples.', concepts=['unit','integration','system','regression','isolation|isolated','requirements'], reference='Unit testing checks small components such as functions in isolation, often using mocks for dependencies. Integration testing verifies that connected components work together, such as an API and database. System testing checks the entire application against its requirements, including user workflows. Regression testing reruns existing tests after changes to detect unintended breakage. For example, a checkout feature needs unit tests for discounts, integration tests for payment services and system tests for the complete purchase flow. A balanced test strategy includes boundary inputs and failure paths, not only successful cases.', partial='Unit testing checks a function in isolation. Integration testing checks components together. Tests help find bugs in software.', paraphrase='A unit test isolates one function and checks its behavior. Integration tests exercise the interaction between modules, for instance a service and its database. System tests cover the complete product against requirements. Regression tests are repeated after an edit to ensure old behavior still works. For a shopping cart, test the price function, payment connection and full checkout workflow. Boundary cases and invalid inputs are also necessary.')
]

# Explicit educator-editable alternatives, not claims of general semantic understanding.
ALIASES = {
    'labelled data|labeled data': 'labelled data|labeled data|paired with correct answers|known target output',
    'classification': 'classification|classifier|classifies',
    'address space|memory space': 'address space|address spaces|memory space|memory spaces',
    'reliable|reliability': 'reliable|reliability|recover lost packets|guaranteed delivery',
    'isolation|isolated': 'isolation|isolated|isolates|isolate',
}
for topic in TOPICS:
    topic['concepts'] = [ALIASES.get(concept, concept) for concept in topic['concepts']]

def records():
    rows = []
    for i, t in enumerate(TOPICS):
        variants = [('complete',t['reference'],96), ('paraphrase',t['paraphrase'],88), ('partial',t['partial'],48), ('brief',t['partial'].split('.')[0]+'.',25), ('off_topic',TOPICS[(i+1)%len(TOPICS)]['reference'],3), ('keyword_list',', '.join(c.split('|')[0] for c in t['concepts']),18), ('repeated', (t['partial'].split('.')[0]+'. ')*10,22), ('expanded',t['reference']+' A practical implementation should be evaluated with representative cases and documented limitations.',93)]
        rows.extend(dict(topic_id=t['id'],variant=v,answer=a,expected_score=s,source='Original synthetic demonstration fixture') for v,a,s in variants)
    return rows
